const photos=[{id:14,title:'함께 모이면 더 좋은, 메인 공간',cat:'day'},{id:4,title:'반짝이는 우리만의 파티',cat:'party'},{id:12,title:'햇살이 머무는 파티 테이블',cat:'day'},{id:19,title:'불빛이 바뀌면, 새로운 분위기',cat:'party'},{id:37,title:'편안하게 쉬어 가는 소파',cat:'day'},{id:21,title:'파티의 텐션을 올리는 조명',cat:'party'},{id:7,title:'우리만의 스크린 타임',cat:'fun'},{id:6,title:'친구들과 함께, 게임 한 판',cat:'fun'},{id:28,title:'편리하게 이용하는 준비 공간',cat:'fun'},{id:38,title:'아늑한 포토 스폿',cat:'day'},{id:34,title:'마이크를 잡고 즐기는 노래 한 곡',cat:'fun'},{id:0,title:'조명 아래 감성 가득한 바',cat:'party'},{id:13,title:'빈백에 기대어 쉬는 시간',cat:'day'},{id:15,title:'창가에서 여유롭게',cat:'day'},{id:35,title:'밤이 되면 더 빛나는 공간',cat:'party'},{id:39,title:'사진으로 남기고 싶은 순간',cat:'day'}];
let category='all',expanded=false,current=0;const gallery=document.querySelector('#gallery'),more=document.querySelector('#more'),dialog=document.querySelector('#lightbox');
function filtered(){return photos.filter(p=>category==='all'||p.cat===category)}
function render(){const list=filtered();gallery.replaceChildren();list.slice(0,expanded?list.length:5).forEach(p=>{const b=document.createElement('button');b.className='gallery-card';b.setAttribute('aria-label',p.title+' 사진 크게 보기');const img=document.createElement('img');img.src=`assets/space-${p.id}.jpg`;img.alt=p.title;img.loading='lazy';const label=document.createElement('span');label.className='label';label.textContent=p.title;const zoom=document.createElement('span');zoom.className='zoom';zoom.textContent='↗';zoom.setAttribute('aria-hidden','true');b.append(img,label,zoom);b.onclick=()=>{current=photos.indexOf(p);showPhoto();dialog.showModal();document.body.style.overflow='hidden'};gallery.append(b)});more.hidden=list.length<=5;more.textContent=expanded?'사진 접어두기 −':`공간 사진 더 보기 (${list.length}장) ＋`}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{category=b.dataset.filter;expanded=false;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});render()});more.onclick=()=>{expanded=!expanded;render();if(!expanded)document.querySelector('#space').scrollIntoView({behavior:'smooth'})};
function showPhoto(){const p=photos[current];document.querySelector('#large-photo').src=`assets/space-${p.id}.jpg`;document.querySelector('#large-photo').alt=p.title;document.querySelector('#photo-caption').textContent=`${p.title} · ${current+1} / ${photos.length}`}
function move(n){current=(current+n+photos.length)%photos.length;showPhoto()}
dialog.querySelector('.close').onclick=()=>dialog.close();dialog.querySelector('.prev').onclick=()=>move(-1);dialog.querySelector('.next').onclick=()=>move(1);dialog.addEventListener('close',()=>document.body.style.overflow='');dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')move(-1);if(e.key==='ArrowRight')move(1)});
document.querySelector('#copy-address').onclick=async()=>{try{await navigator.clipboard.writeText('서울특별시 용산구 청파로45길 37, 2층');document.querySelector('#copy-status').textContent='주소를 복사했어요.'}catch{document.querySelector('#copy-status').textContent='서울특별시 용산구 청파로45길 37, 2층 — 주소를 선택하여 복사해 주세요.'}};render();
